    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is None:
        handlers = {v: cls.protocol_version_handlers[v] for v in cls.KATCP_PROTOCOLS}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError('protocol version must be a tuple')
        if protocol_version not in cls.KATCP_PROTOCOLS:
            raise ValueError(f'protocol version not supported, {protocol_version}')
        handlers = {protocol_version: cls.protocol_version_handlers[protocol_version]}

    return handlers

