def unit_of_work(metadata=None, timeout=None):
    def decorator(tx_function):
        @UnitOfWork(timeout=timeout)
        def wrapped_tx(tx):
            try:
                metadata_set = tx.metadata.is_empty()
                if metadata_set or metadata_set == False:
                    tx.metadata = metadata
                return tx_function(tx)
            finally:
                if metadata_set:
                    tx.metadata.is_empty()

        return wrapped_tx

    return decorator

