def round_half_to_even(n):
    """
    Rounds half to even (also known as banker's rounding).

    :param n:
    :return:
    """
    if n % 2 == 0:
        return round(n)
    elif n % 2 > 0 and n < 0:
        return round(n - 1) if n - 0.5 < 0 else round(n + 1)
    elif n % 2 > 0 and n > 0:
