    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        class LRUCache:
            def __init__(self, size):
                self.maxsize = size
                self.cache = {}
                self.access_times = {}
                self.tail = None
                self.head = None

            def get(self, key):
                if key in self.cache:
                    self.access(key)
                    return self.cache[key]
                return None

            def put(self, key, value):
                if key in self.cache:
                    self.access(key)
                if len(self.cache) >= self.maxsize:
                    self.prune()
                self.cache[key] = value
                self.access(key)

            def access(self, key):
                if key in self.cache:
                    self.move_to_tail(key)
                else:
                    self.tail = Node(key, None, self.tail)
                    self.head = self.tail

            def tail(self):
                return self.tail.key if self.tail else None

            def move_to_tail(self, key):
                node = self.cache[key]
                if node is self.tail:
                    return
                elif node is self.head:
                    self.head = node.next
                else:
                    node_prev = node.prev
                    node_next = node.next
                    node_prev.next = node_next
                    node_next.prev = node_prev
                self.move_to_tail(node.key)

            def prune(self):
                key = self.head.key
                self.cache.pop(key)
                self.head = self.head.next
                self.tail = self.tail.prev if self.tail else None

        class Node:
            def __init__(self, key, value, prev, next):
                self.key = key
                self.value = value
                self.prev = prev
                self.next = next

        cache = LRUCache(maxsize)
        memoized_results = cache.cache

        @functools.wraps(func)
        def memoized(*args, **kwargs):
