        def put(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())), timer(), typed)
            yield functools.partial(cache.put, key)

        def forget(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())), timer(), typed)
            if key in memoized_results:
                cache.remove(key)

        def clear():
            memoized_results.clear()

        return memoized, put, forget, clear

