def mru_cache(maxsize=128, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves up to `maxsize`
    results based on a Most Recently Used (MRU) algorithm.

    """
    def decorator(fn):
        if fn is None:
            # We're being applied as a decorator factory; ie: the user has supplied args, like so:
            # >>> @mru_cache(maxsize=256)
            # ... def my_function(parameter1, parameter2):
            # ...   pass
            # So we return a decorator with the user-supplied args curried in for the python decorator
            # machinery to use to wrap the upcoming func.
            #
            # NB: This is just a tricky way to allow for both `@cache` and `@cache(...params...)`
            # application forms.  Without this trick, ie: using a decorator class or nested decorator
            # function, the no-params application would have to be `@cache()`.  It still can, but need
            # not be and a bare `@cache` will work as well as a `@cache()`.
            return functools.partial(mru_cache, maxsize=maxsize, typed=typed)

        if not inspect.isfunction(fn):
            raise ValueError('The @mru_cache decorator must be applied innermost of all decorators.')

        key_func = functools.lru_cache(maxsize=maxsize, typed=typed).cache_info().key_func
        memoized_results = {"last_reqs": [], "lru_size": 0, "mru": {}}

        @functools.wraps(fn)
        def memoize(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in memoized_results["mru"]:
                memoized_results["last_reqs"].remove(key)
                memoized_results["mru"][key]["last_used"] = time.time()
                memoized_results["lru_size"] = len(memoized_results["last_reqs"])
                return memoized_results["mru"][key]["value"]
            result = fn(*args, **kwargs)
            memoized_results["last_reqs"].append(key)
            memoized_results["mru"][key] = {
                "value": result,
                "last_used": time.time()
            }
            memoized_results["lru_size"] = len(memoized_results["last_reqs"])
            if memoized_results["lru_size"] > maxsize:
                del memoized_results["last_reqs"][0]
                del memoized_results["mru"][memoized_results["last_reqs"][0]]
            return result

        @contextmanager
        def put(*args, **kwargs):
            key = key_func(*args, **kwargs)
            yield functools.partial(memoized_results["mru"].__setitem__, key)
        memoize.put = put

        def forget(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in memoized_results["mru"]:
                del memoized_results["last_reqs"][memoized_results["last_reqs"].index(key)]
                del memoized_results["mru"][key]
        memoize.forget = forget

        def clear():
            memoized_results["last_reqs"] = []
            memoized_results["mru"] = {}
            memoized_results["lru_size"] = 0
        memoize.clear = clear

        return memoize

    return decorator

