    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        return e.__str__()
    except Exception:
        try:
            return f"exception of type {type(e).__name__} with message {e.message}"
        except Exception:
            return "Failed to capture exception"

def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        exc_info = sys.exc_info()
        exc = exc_info[1]
        if exc_info[2] is None:
            exc_tb = None
        else:
            exc_tb = exc_info[2]
        if exc_tb is None:
            exc_frame = None
            exc_tb_str = None
        else:
            exc_frame = exc_tb.tb_frame
            exc_tb_str = exc_tb.tb_frame.f_code.co_name
        exc_name = exc.__class__.__name__
        path, line, name, src = '', '', '', None
        if exc_frame:
            path, line, name, src = exc_frame.f_code.co_filename, exc_frame.f_lineno, exc_frame.f_code.co_name, exc_frame.f_code.co_firstlineno
        retd = {
            'msg': str(e),
            'file': path,
            'line': line,
            'name': name,
            'src': src
        }
        if isinstance(e, s_exc.SynErr):
            retd['syn:err'] = e.errinfo

        return (e.__class__.__name__, retd)
    except Exception as e:
        log.error(f"Error formatting exception: {e}")
        return ("Exception", {"msg": str(e)})

