def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in sorted(classes):
        if cls in seen:
            continue
        seen.add(cls)
        result.append(cls)
    return result

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent

    Args:
        classes (List[Type]): A list of base classes

    Returns:
        List[Type]: A list of base classes, ordered by their inheritance hierarchy
    """
    if not classes:
        return []

    # Create a dictionary to store classes and their inheritance hierarchy
    hierarchy = {cls: cls.__bases__ for cls in classes}

    # Perform the reduction by updating the hierarchy
    while True:
        updated = False
        for cls, bases in hierarchy.items():
            if not bases:
                continue
            new_bases = set()
            for base in bases:
                if base in hierarchy:
                    new_bases.update(hierarchy[base])
            hierarchy[cls] = new_bases
            updated = True
        if not updated:
            break

    # Extract the_ordered minimum equivalent classes
    minimal_classes = []
    visited = set()
    for cls in classes:
        path = [cls]
        while cls in hierarchy:
            cls = hierarchy[cls]
            if cls in visited:
                path.append(cls)
                break
            path.append(cls)
            visited.add(cls)
        minimal_classes.extend(reversed(path))

    return minimal_classes

