import numpy as np

def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    integral_scale = None
    if endpointed(bins) and closed(bins):
        # The bin edges are off by half a bin.
        # Use this to calculate the integral scale
        integral_scale = (edges[1] - edges[0]) / 2

    if integral_scale is not None:
        return integral_scale * np.diff(bins)
    else:
        if len(bins) != len(edges) - 1:
            raise ValueError("The number of bins must be one less than the number of edges.")
        return np.diff(edges)

def endpointed(bins):
    """
    Check if the bin edges are endpointed.
    """
    return bins.dtype.name == 'float' and bins[0] == -np.inf or bins[-1] == np.inf

def closed(bins):
    """
    Check if the bin edges are closed.
    """
    return bins.dtype.name == 'float' and (-np.inf not in bins) and (np.inf not in bins)

