def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level <= 0:
        # no recursion, just compare dictionaries
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        # perform recursive difference
        diff = {}
        for k in d1:
            if k in d2:
                if isinstance(d1[k], dict) and isinstance(d2[k], dict):
                    diff[k] = difference(d1[k], d2[k], level - 1)
                elif d1[k] != d2[k]:
                    diff[k] = d1[k]
            else:
                diff[k] = d1[k]
        return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level != -1:
        if isinstance(d1, dict) and isinstance(d2, dict):
            difference = {}
            for key, value in d1.items():
                if key in d2:
                    if isinstance(value, dict) and isinstance(d2[key], dict):
                        if level == 1:
                            if value.keys() == d2[key].keys() and all(d1[key][k] == d2[key][k] for k in value.keys()):
                                continue
                            else:
                                difference[key] = d1[key]
                        else:
                            if level == 2:
                                difference[key] = {k: d1[key][k] for k in value.keys() if not k in d2[key]}
                            elif level == 3:
                                difference[key] = {k: d1[key][k] for k in value.keys() if k in d2[key] and not k in value}
                            else:
                                difference[key] = difference[key]
                        difference.update(difference)
                    else:
                        if isinstance(value, dict):
                            difference[key] = difference[key]
                        else:
                            if level == 1:
                                if value != d2[key]:
                                    difference[key] = d1[key]
                            else:
                                if value != d2[key]:
                                    difference[key] = difference[key]
                                else:
                                    difference[key] = difference[key]
                            difference.update(difference)
                else:
                    difference[key] = value
            return difference
        else:
            return d1
    else:
        set2 = set(d2.keys())
        difference = {k: v for k, v in d1.items() if k not in set2}
        return difference

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        # infinite recursion
        return {k: v for k, v in d1.items() if k not in d2}
    elif level > 0:
        # non-infinite recursion
        result = {}
        for k, v in d1.items():
            if k in d2:
                if isinstance(v, dict):
                    # recurse into the dictionary
                    recurse_result = difference(v, d2[k], level - 1)
                    if recurse_result:
                        result.update(recurse_result)
                elif v != d2[k]:
                    # item is different
                    result[k] = v
            else:
                # item is new
                result[k] = v
        return result
    else:
        # level <= 0: invalid argument
        raise ValueError("Invalid level value")

