def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple):
        raise TypeError('coord must be a tuple')
    if len(coord) != self._ndim:
        raise ValueError('coord must have the same number of elements as the histogram')

    bin_indices = [max(0, int((value - self.min) / self.width)) for value in coord]
    if min(bin_indices) < 0 or max(bin_indices) >= self._Nbins:
        return False

    self._hist[bin_indices] += weight
    return True

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self.edges is None:
        raise ValueError("Histogram not initialized.")
    if coord < self.edges[0] or coord >= self.edges[-1]:
        return
    self.values[int((coord - self.edges[0]) / self.bin_size)] += weight

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.

    """

    if np.isscalar(coord):
        coord = [coord]

    if not hasattr(self, 'bins'):
        self.bins = [0]

    if not hasattr(self, 'hist'):
        self.hist = [0]

    for x in coord:
        for i in range(len(self.bins)):
            if x < self.bins[i]:
                break
        else:
            i = len(self.hist)
        self.hist.insert(i, self.hist[i - 1] + weight if i > 0 else weight)
        self.bins.insert(i, x)

