def generate_default_observer_schema_dict(manifest_dict: Dict[str, Any], first_level: Optional[bool] = False) -> Dict[str, Any]:
    new_dict = {}
    for key, value in manifest_dict.items():
        if not isinstance(value, list) and not isinstance(value, dict):
            new_dict[key] = None
        else:
            new_dict[key] = generate_default_observer_schema_dict(value, first_level)

    if first_level:
        # Assuming the details of identifying fields extraction and copying from text is handled elsewhere
        for key in ['apiVersion', 'kind', 'metadata']:
            if key in manifest_dict:
                new_dict[key] = manifest_dict[key]

    return new_dict

from typing import Union, Dict, Any

def generate_default_observer_schema_dict(manifest_dict: Dict[str, Any], first_level: bool = False) -> Dict[str, Any]:
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            result[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else item for item in value]
        else:
            result[key] = None
    if first_level:
        for field in ['name', 'kind']:
            if field in manifest_dict:
                result[field] = manifest_dict[field]
    return result

