def query(self, sql: AnyStr, args: Union[Dict[Union[str, int], Any], Sequence[Any]], many=None, as_dict=False):
    con = self.pool.pop()
    c = None
    try:
        c = con.cursor(as_dict)
        LOGGER.debug("Query sql: " + sql + " args:" + str(args))
        c.execute(sql, args)
        if many and many > 0:
            return self._yield(con, c, many)
        else:
            return c.fetchall()

    except Exception as e:
        LOGGER.error("Error Qeury on %s", str(e))
        raise DBError(e.args[0], e.args[1])
    finally:
        many or (c and c.close())
        many or (con and self.pool.push(con))

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        return True
    try:
        import os
        if not os.path.exists(path):
            return False
        if not (path.endswith('.json') or path.endswith('.jsonl')) and not path.endswith('.md'):
            return False
    except Exception:
        return False
    return True

import os

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path and not self.raise_validation_errors:
            return True
        if not os.path.exists(path):
            raise Exception(f"'{path}' does not exist")
        if not os.path.isabs(path):
            raise Exception(f"'{path}' is not an absolute path")
        if not self.has_ocfl_header(path):
            raise Exception(f"'{path}' is not an OCFL root or object")
        return True
    except Exception as e:
        if self.raise_validation_errors:
            raise Exception(e)
        return False

