def is_valid(identifier):
    """Return True if identifier is valid, always True in this base implementation."""
    if not isinstance(identifier, str):
        raise TypeError("identifier must be a string")

    IDENTIFIER_FORM_RE = re.compile(r'[^_0-9a-zA-Z]')

    if not IDENTIFIER_FORM_RE.match(identifier):
        return False

    if identifier.upper() in ['TRUE', 'FALSE', 'NULL']:
        return False

    return True

