def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not inventory:
        raise ValueError("Inventory cannot be empty.")

    if extract_spec_version:
        if 'type' not in inventory:
            if 'specification_version' in self.spec_version:
                specification_version = self.spec_version['specification_version']
            elif 'inventory_version' in self.spec_version:
                specification_version = self.spec_version['inventory_version']
            else:
                raise ValueError("Need either 'type' or 'specification_version' in inventory.")
        elif isinstance(inventory['type'], Schema):
            # Nested documents cannot have validation
            if not set(inventory['type'].keys()).issubset(set(['type', 'required', 'nullable', 'default'])):
                raise SchemaFormatException("Unsupported field spec item at {}. Items: "+repr(inventory['type'].keys()), ['type'])
            return
        elif isinstance(inventory['type'], Array):
            if not isinstance(inventory['type'].contained_type, (type, Schema, Array, types.FunctionType)):
                raise SchemaFormatException("Unsupported field type contained by Array at {}.", ['type'])

        elif not isinstance(inventory['type'], type) and not isinstance(inventory['type'], types.FunctionType):
            raise SchemaFormatException("Unsupported field type at {}. Type must be a type, a function, an Array or another Schema", ['type'])

    if 'items' in inventory:
        for item in inventory['items']:
            self._validate_item(item, "items")
    elif 'virtual_columns' in inventory:
        for column in inventory['virtual_columns']:
            self._validate_item(column, "virtual_columns")
    elif 'schemas' in inventory:
        for schema in inventory['schemas']:
            self._validate_schema(schema)

    if 'measurement_types' in inventory:
        for measurement_type in inventory['measurement_types']:
            self._validate_measurement_type(measurement_type, "measurement_types")

    if 'groups' in inventory:
        for group in inventory['groups']:
            self._validate_group(group, "groups")

    if 'metrics' in inventory:
        for metric in inventory['metrics']:
            self._validate_metric(metric, "metrics")

    if 'descriptors' in inventory:
        for descriptor in inventory['descriptors']:
            self._validate_descriptor(descriptor, "descriptors")

    if 'variables' in inventory:
        for variable in inventory['variables']:
            self._validate_variable(variable, "variables")

    if 'settings' in inventory:
        for setting in inventory['settings']:
            self._validate_setting(setting, "settings")

    if 'sources' in inventory:
        for source in inventory['sources']:
            self._validate_source(source, "sources")

    if 'extractors' in inventory:
        for extractor in inventory['extractors']:
            self._validate_extractor(extractor, "extractors")

    if 'visualization_pipeline_steps' in inventory:
        for step in inventory['visualization_pipeline_steps']:
            self._validate_visualization_pipeline_step(step, "visualization_pipeline_steps")

    if 'profiles' in inventory:
        for profile in inventory['profiles']:
            self._validate_profile(profile, "profiles")

    if 'recommended_settings' in inventory:
        for setting in inventory['recommended_settings']:
            self._validate_setting(setting, "recommended_settings")

    if 'dtype_columns' in inventory:
        for dtype_column in inventory['dtype_columns']:
            self._validate_dtype_column(dtype_column, "dtype_columns")

    if 'map_configurations' in inventory:
