    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check if the prior is an instance of InventoryValidator
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The input variable prior must be an instance of InventoryValidator")

    # Check if both inventories have been checked for internal consistency
    if not self.is_valid:
        raise ValueError("The current inventory object is not valid")
    if not prior.is_valid:
        raise ValueError("The input inventory object is not valid")

    # Add condition to check that prior's parameters are all present in self's parameters
    for param in prior.parameters:
        if param not in self.parameters:
            raise ValueError('Prior has parameter(s) not present in current inventory parameters')

    return True

def get_logical_path_map(inventory, version):
    logical_paths = {}
    content_files = set()

    for item in inventory:
        logical = item['logical_path']
        content_file = item['content_file']

        if version in item:
            content_files.update(item[version])

        if logical not in logical_paths:
            logical_paths[logical] = {content_file}
        else:
            logical_paths[logical].add(content_file)

    return logical_paths

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for state in inventory:
        for file_path in state.content_files:
            logical_path = file_path.relative_to(inventory.root)
            logical_path_map[logical_path] = logical_path_map.get(logical_path, set()) | {file_path}
    return logical_path_map

