    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        return

    if not isinstance(fixity, dict) or 'type' not in fixity or 'content' not in fixity:
        raise ValueError("Fixity block is not in the expected format")

    if fixity['type'] != 'md5' and fixity['type'] != 'sha256':
        raise ValueError(f"Unsupported fixity type: {fixity['type']}")

    for file_hash, file_path in fixity['content'].items():
        if file_path not in manifest_files:
            raise ValueError(f"File not found in manifest: {file_path}")

