def _extract_number_and_supplement_from_issue_element(issue):
    result = {}

    # Split the issue text by ' Suppl' or ' suppl'
    parts = issue.split(' Suppl')

    for i in range(len(parts)):
        # Strip extra spaces
        item = parts[i].strip()

        # Check if the item starts with a number
        if item.startswith('0'):
            number = item[0]
            if i + 1 < len(parts) and parts[i + 1].startswith(' Suppl'):
                suppl = parts[i + 1][6:]
            else:
                suppl = '1'
            result[f'number{i + 1}'] = number
            if suppl:
                result[f'suppl{i + 1}'] = suppl
        else:
            number = ''
            suppl = '1'
            result[f'number1'] = number
            result[f'suppl1'] = suppl

    return result

import re

def _extract_number_and_supplment_from_issue_element(issue):
    # Extract the number and suppliment from the issue text
    match = re.search(r'<issue>([^<]+)</issue>', issue)
    if match:
        number = match.group(1).strip()
        supplement = re.findall(r'(\d+-?\d?|\d+s\d{1,2}|sup\d{1,2}|pr\d{1,=2}|spe|\-?\d+(\.\d+)?|\-\d+(\.\d+)?)', number)
        return number, supplement
    else:
        return None, []

