    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    index = 2
    abs2 = []
    abs1 = []
    while index < len(args):
        if args[index] == 'A':
            if index < len(args) - 1 and args[index + 1] == '&':
                abs2.append('A & A')
            elif index < len(args) - 1 and args[index + 1] == '|':
                abs2.append('A | A')
            elif index < len(args) - 1 and args[index + 1] == '~':
                if abs1:
                    if isinstance(abs1[0], str):
                        abs1.append('~A')
                    elif isinstance(abs1[0], int):
                        abs1.append('not ' + str(abs1[0]))
                abs2.append('A')
            elif args[index - 1] == '~':
                if abs1:
                    if isinstance(abs1[0], str):
                        abs1.append('not A')
                    elif isinstance(abs1[0], int):
                        abs1.append('not ' + str(abs1[0]))
            index += 2
        elif args[index] == 'A':
            if index < len(args) - 1 and args[index + 1] == '&':
                abs1.append('A & A')
            elif index < len(args) - 1 and args[index + 1] == '|':
                abs1.append('A | A')
            elif index < len(args) - 1 and args[index + 1] == '~':
                if abs2:
                    if isinstance(abs2[0], str):
                        abs2.append('~A')
                    elif isinstance(abs2[0], int):
                        abs2.append('not ' + str(abs2[0]))
                abs1.append('A')
            elif args[index - 1] == '~':
                if abs2:
                    if isinstance(abs2[0], str):
                        abs2.append('not A')
                    elif isinstance(abs2[0], int):
                        abs2.append('not ' + str(abs2[0]))
            index += 2
        else:
            abs2.append(args[index])
            index += 1
    return abs1 + abs2

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.startswith('A & ('):
            a_side = arg[:arg.index(')')]
            b_side = arg[arg.index(')')+1:-1]
            if a_side.endswith('|'):
                new_args.append(a_side.replace('|', '+') + "&")
            else:
                new_args.append(a_side + '*')

            if b_side.startswith('|'):
                new_args.append(b_side[:b_side.index('|')] + '+')
            else:
                new_args.append(b_side + '*')
        elif arg.startswith('A | ('):
            a_side = arg[:arg.index(')')]
            b_side = arg[arg.index(')')+1:-1]
            if a_side.startswith('|'):
                new_args.append(a_side.replace('|', '+') + "|")
            else:
                new_args.append(a_side + '*')

            if b_side.startswith('|'):
                new_args.append(b_side[:b_side.index('|')] + '|')
            else:
                new_args.append(b_side + '*')
        elif arg.startswith('A & (~A |'):
            a_side = arg[:arg.index(')')]
            b_side = arg[arg.index(')')+1:-1]
            if b_side.startswith('|'):
                new_args.append(b_side[:b_side.index('|')] + '+')
            else:
                new_args.append(b_side + '*')

        else:
            new_args.append(arg)
    return new_args

