    """
    Return a + if we don't already have one, else return a .

    :param pieces:
    :return:
    """
    result = []
    has_plus = False
    for piece in pieces:
        if piece == '+' and not has_plus:
            result.append('+')
            has_plus = True
        else:
            result.append(piece)
    return ''.join(result)

