class ProgramError(Exception):
    pass

def run_command(commands: List[str], args: List[str], cwd: str = None, verbose: bool = False, hide_stderr: bool = False, env: dict = None) -> None:
    # Construct the command list
    cmd_list = [command] if cwd is None else [cwd] + command
    cmd_list.extend(args)

    try:
        # Run the command
        output = subprocess.run(cmd_list, capture_output=verbose, text=True, env=env)
        if output.returncode != 0:
            if hide_stderr:
                print("Command failed.")
                print("Output: ", output.stderr, file=stderr)
            else:
                print("Command failed with returncode:", output.returncode)
                print("stdout: ", output.stdout, file=stdout)
                print("stderr: ", output.stderr, file=stderr)
            raise ProgramError(output.stderr)
        else:
            if verbose:
                print("Command executed successfully.")
                print("Output: ", output.stdout)

    except Exception as e:
        print(f"Error running command: {e}")
        print_usage()

