import re

from typing import Tuple

def next_version(version: str) -> str:
    pattern = re.compile(r'(^|\D)(0+[0-9]*)\.([0-9]+)\.(0+[0-9]*)')
    match = pattern.match(version)

    if match:
        release, major, minor = match.groups()

        if minor:
            minor = str(int(minor) + 1)
            if minor == '00':
                minor = '01'
            elif minor == '10':
                minor = '11'
            elif minor == '20':
                minor = '21'
            elif minor == '30':
                minor = '31'
            elif minor == '40':
                minor = '41'
            elif minor == '50':
                minor = '51'
            elif minor == '60':
                minor = '61'
            elif minor == '70':
                minor = '71'
            elif minor == '80':
                minor = '81'
            elif minor == '90':
                minor = '91'

        return f"{release}{major}.{minor}"
    else:
        raise ValueError("Invalid version format")

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.startswith('0'):
        return '0.' + str(int(version.lstrip('0')) + 1)
    else:
        parts = version.split('.')
        new_part = str(int(parts[-1]) + 1)
        return '.'.join(parts[:-1]) + '.' + new_part

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """

    if version.split('.').count('0') == len(version.split('.')):
        return '1.0.0'

    version_parts = version.split('.')
    version_parts[-1] = str(int(version_parts[-1]) + 1)
    return '.'.join(version_parts)

import packaging.specifiers

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    latest_version = None
    digests = {}

    for version in version_dirs:
        try:
            packaging.specifiers.SpecifierSet(version)
        except packaging.specifiers.InvalidSpecifier as error:
            raise ValueError(f"{version!r} is not a valid version specifier")

        if latest_version is not None and packaging.specifiers.SpecifierSet VERSION_SET) > packaging.specifiers.SpecifierSet(latest_version):
            latest_version = version
        elif latest_version is None:
            latest_version = version

    # Ensure there is at least one valid version
    if latest_version is None:
        raise ValueError("No versions are specified")

    # Add translations to the digests dictionary
    for version in version_dirs:
        if version in self.digs:
            digests[version] = {'content_digests': self.digs[version]['content_digests'],
                                'digest_contents': self.digs[version]['digest_contents']}
        else:
            digests[version] = {'content_digests': {},
                                'digest_contents':}

    return latest_version, digests

import os

def find_path_type(path):
    try:
        stats = os.stat(path)
        if stats.st_size == 0:
            return 'root'
        elif 'namaste' in path:
            return 'object'
        else:
            return 'file'
    except Exception as e:
        return str(e)

def find_path_type(path):
    # Check for '0=*' pattern
    if path.startswith('0='):
        return 'root'

    # Check for 'ocfl/0=1' pattern
    if path.startswith('ocfl/0=1'):
        return 'object'

    # Check for 'ocfl/data/1=ens_data/' pattern to determine file type
    if path.startswith('ocfl/data/1=ens_data/'):
        return 'file'

    # Default case for unsupported paths
    return 'other string explains error description'

