            merged_nodes[key] = value
    return [(key, merged_nodes[key]) for key in merged_nodes]

def deep_merge_nodes(nodes):
    merged_result = {}
    seen_keys = {}

    for key, value in nodes:
        if key in seen_keys:
            if isinstance(seen_keys[key], MappingNode):
                if isinstance(value, MappingNode):
                    merge_nodes(seen_keys[key], value)
                else:
                    seen_keys[key].yaml_set_value(value)
            else:
                seen_keys[key] = value
        else:
            seen_keys[key] = value

    return list(merged_result.items())

