from collections import defaultdict

from typing import Any, Dict, List, Tuple

class Node:
    def __init__(self, value: Any, children: List['Node'] = None):
        self.value = value
        self.children = children if children is not None else []

    def __repr__(self):
        children_str = ' '.join([repr(child) for child in self.children])
        return f"Node instance with value {self.value} with {len(self.children)} links: {children_str}"

def deep_merge_nodes(nodes: List[Tuple[Node, Node]]) -> List[Tuple[Node, Node]]:
    value_map = defaultdict(Node)
    for key, value in nodes:
        while key in value_map:
            value = value_map[key]
        value_map[key] = value if value.value == key.value else Node(value.value)

    merged_nodes = [(key, value) for key, value in value_map.items()]
    return sorted(merged_nodes, key=lambda x: (x[0].tag, x[0].value))

def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    commands = {}

    for name, cmd_func in borgmatic.commands.items():
        subcommands = {}
        for subcmd, subcmd_func in cmd_func.commands.items():
            subcommands[subcmd] = cmd_func.parameters[subcmd].opts

        commands[name] = subcommands

    identifiers = []

    def print_identifier(name):
        identifiers.append(name)
        if name in commands:
            for subcmd, opts in commands[name].items():
                for opt in opts:
                    print_identifier(f"{name}.{subcmd}.{opt}")

    print_identifier('borgmatic')

    max_len = max(len(identifier) for identifier in identifiers)

    for identifier in identifiers:
        print(f"{identifier:{max_len}}")

