def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    result = ""
    while number > 0:
        remainder = number % len(alphabet)
        result = alphabet[remainder] + result
        number //= len(alphabet)
    if padding is not None:
        result = result.zfill(padding)
    return result

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

