import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    comm_pattern = re.compile(r'\b(\s*[\'"\`])?)((?:\\\1)?[^\'"]+)')
    tokens = re.findall(comm_pattern, s)

    tokens = [t for t in tokens if t[1]]
    if platform == 'windows':
        tokens = [t.replace('"', r'\"') for t in tokens]
    elif platform == 'cmd':
        tokens = [t.replace('"', r'\"') for t in tokens]
        tokens = [t.replace(r'?', r'\\?') for t in tokens]
    elif platform == 'this':
        if re.match(r'^([a-z])', s[0]).group(1) in '([TtFfSs]a?)':
            tokens = [t.replace('"', r'\"') for t in tokens]
        elif re.match(r'^([a-z])', s[0]).group(1) in '([Pp])':
            tokens = [t.replace('"', r'\"') for t in tokens]
        elif re.match(r'^([a-z])', s[0]).group(1) in '([Ee])':
            tokens = [t.replace('"', r'\"') for t in tokens]
    return tokens

