import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Check for presence of 'if __name__' block
    if __name__ == "__main__":
        # Perform system-specific split variant
        if platform == '1':
            # POSIX split
            return re.split(r' ', s)
        elif platform == '0':
            # Windows split
            return [s.split(' ')]
        else:
            # Auto determine platform and return corresponding split variant
            if 'win' in platform.lower():
                return re.split(r' ', s)
            else:
                return re.split(r' ', s)
    else:
        # If not a script, just return the split string
        return s.split(' ')

