        elif archive_path.endswith('.tar.bz2'):
            filename = 'archive.tar.bz2'
        else:
            _, ext = os.path.splitext(archive_path)
            if ext:
                ext = ext[1:]  # Trim leading '.'.
            if not ext:
                raise ValueError('Could not determine archive type of path {}'.format(archive_path))
            filename = 'archive.' + ext

    if not os.path.exists(filename):
        raise FileNotFoundError(filename)

    if not os.path.isfile(filename):
        raise IsADirectoryError(filename)

    subprocess.run(['tar', 'xzf', filename, '-C', tmp_path])

    # Assuming the files are extracted to tmp_path and we need to create a repo url
