def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if not frequency.return_type:
        return None if frequency.value == 0 else None if frequency.value == "always" else ValueError("Invalid frequency")

    valid_units = ["hours", "minutes", "seconds", "days", "weeks", "months", "years"]

    parsed_units = ['hours', 'minutes', 'seconds']
    parsed_values = []
    frequency_str = frequency.value

    for i, unit in enumerate(parsed_units):
        if frequency_str.startswith(unit):
            parsed_units.append(unit)
            parsed_values.append(int(frequency_str.split(unit)[1]))
            frequency_str = ""
            if i > 0 and parsed_units[i] == parsed_units[i-1]:
                raise ValueError(f"Duplicate unit {unit}")
            if i + 1 < len(parsed_units):
                if parsed_units[i + 1] != "hours" and parsed_units[i + 1] not in parsed_units:
                    raise ValueError(f"Invalid unit after {unit}")
            if i == 0:
                continue

    if frequency_str:
        raise ValueError("Invalid format of the frequency")

    if parsed_units[0] == "years":
        return datetime.timedelta(days=365 * sum(parsed_values))
    elif parsed_units[0] == "weeks":
        return datetime.timedelta(days=sum(parsed_values) * 7)
    elif parsed_units[0] == "days":
        return datetime.timedelta(days=sum(parsed_values))
    elif parsed_units[0] == "hours":
        return datetime.timedelta(hours=sum(parsed_values))
    elif parsed_units[0] == "minutes":
        return datetime.timedelta(minutes=sum(parsed_values))
    elif parsed_units[0] == "seconds":
        return datetime.timedelta(seconds=sum(parsed_values))
    else:
        raise ValueError("Invalid units in the frequency")

