        return datetime.timedelta(days=num)

def parse_frequency(frequency):
    """Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency in ("always", None):
        return None

    if not re.match(r'^\d+(\.\d+)?$', frequency):
        raise ValueError("Invalid frequency format")

    parts = frequency.split()
    for part in parts:
        if not re.match(r'(\d+(\.\d+)?)([a-zA-Z]+)', part):
            raise ValueError("Invalid frequency format")

    if "weekly" in parts:
        return datetime.timedelta(weeks=float(parts[parts.index("weekly") + 1]))

    if "monthly" in parts:
        return datetime.timedelta(days=float(parts[parts.index("monthly") + 1]) * 30)

    if "quarterly" in parts:
        return datetime.timedelta(days=float(parts[parts.index("quarterly") + 1]) * 90)

    if "yearly" in parts:
        return datetime.timedelta(days=float(parts[parts.index("yearly") + 1]) * 365)

