def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    import re

    def is_glob(path):
        return path.startswith('sh:' and not path.endswith('/**'))

    def to_glob(path):
        if is_glob(path):
            return path
        return "sh:*/*" + path

    result = []
    for path in find_paths:
        if is_glob(path):
            result.append(path)
        else:
            result.append(to_glob(path))
    return result

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    def convert_to_glob(path):
        if path.startswith('*'):
            return '*' + path
        elif path.endswith('*'):
            return f'{path}*' 
        else:
            return path.replace('/', '\\')

    return [convert_to_glob(path) for path in find_paths if '*' in path or '**' in path]

def make_find_paths(find_paths):
    import re
    results = []
    for path in find_paths:
        if re.match(r'\w+:[^/#]*', path):
            # Express paths as .path:pattern
            results.append(f'.:{path}')
        else:
            # Treats first wildcards as morf (for example, foo* -> *foo*)
            results.append(re.escape(path.replace('*.*', '*.'))
    return results

