def find_roots(graph, prop, roots=None):
    todo = []
    done = set()
    roots = set() if roots is None else roots

    for s, p, o in graph.triples((None, prop, None)):
        if o not in graph:
            continue
        if o.is_node():
            todo.append(o)

    while todo:
        node = todo.pop(0)
        if node in done:
            continue

        done.add(node)
        if node in roots:
            continue

        todo.extend(graph.get_objects(subject=node, predicate=prop))

    return roots

