def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()

    stack = [node for node in graph.subjects(predicate=prop) if not graph.predecessors(node)]
    while stack:
        current_node = stack.pop()
        for parent in graph.predecessors(current_node):
            if parent not in roots:
                roots.add(parent)
                stack.append(parent)

    return roots

