import logging

from typing import List, Union

def load_configurations(config_filenames: List[str], overrides: Union[None, dict] = None, resolve_env: bool = True) -> Tuple[dict, List[logging.LogRecord]]:

    log = logging.getLogger(__name__)

    # Define the default dictionary for logging
    default_logging_config = {
        'version': 1,
        'disable_existing_loggers': False,
        'formatters': {
            'standard': {
                'format': '%(asctime)s - %(name)s - [%(levelname)s] - %(message)s'
            }
        },
        'handlers': {
            'console': {
                'level': 'DEBUG',
                'class': 'logging.StreamHandler',
                'formatter': 'standard'
            }
        },
        'loggers': {
            '': {
                'level': 'DEBUG',
                'handlers': ['console']
            }
        }
    }

    # Process each configuration file
    configuration_data = {}
    errors = []

    for filename in config_filenames:
        log.info(f"Loading configuration from {filename}")
        try:
            if resolve_env:
                # Load environment variables into the configuration
                with open(filename, 'r') as file:
                    config_content = file.read()
                    config_content = config_content.format(**os.environ)
                    config_data[filename] = toml.loads(config_content)
            else:
                config_data[filename] = toml.loads(open(filename, 'r').read())
            if overrides:
                config_data[filename].update(overrides)
        except FileNotFoundError:
            log.error(f"Configuration file {filename} not found.")
            errors.append(log.error)
        except toml.TomlDecodeError:
            log.error(f"Error parsing configuration file {filename}.")
            errors.append(log.error)
        except Exception as e:
            log.error(f"An error occurred while processing configuration file {filename}: {e}")
            errors.append(log.error)

    # Configure logging using the loaded configurations
    if errors:
        log.error("There were errors loading or validating configurations. Logging will not be configured correctly.")
        return configuration_data, errors

    if resolve_env:
        _configure_logging(default_logging_config, logger_dict=config_data[config_filenames[0]])
    else:
        _configure_logging(default_logging_config)

    return configuration_data, errors

