def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    supported_versions = []
    for handler in cls._handlers.values():
        protocol = handler.get_protocol_version()
        if protocol:
            supported_versions.append(protocol)

    if not supported_versions:
        return {}

    supported_versions = set(supported_versions)
    if not protocol_version:
        protocol_version = tuple(sorted(supported_versions))

    return {protocol_version: handler for protocol_version, handler in cls._handlers.items() if protocol_version == protocol_version}

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    def protocol_version_tuple(version):
        parts = version.split('.')
        if len(parts) == 1:
            return (int(parts[0]), 0)
        elif len(parts) == 2:
            return (int(parts[0]), int(parts[1]))
        else:
            raise TypeError("Protocol version must be in the form (major, minor)")

    protocol_versions = []
    for td in cls.TD:
        if td is not None:
            parts = td & 0x0F
            protocol_versions.append(protocol_version_tuple(parts))

    handlers = {}
    for version in protocol_versions:
        if protocol_version == version:
            if cls hasTD[version]:
                handlers[version] = cls.protocol_handlers[version]
            else:
                handlers[version] = None
        elif version in cls.protocol_handlers:
            handlers[version] = cls.protocol_handlers[version]
        else:
            if version == (0, 0) and cls.hasTD[0]:
                handlers[version] = cls.protocol_handlers[0]
            else:
                handlers[version] = None

    return handlers

