def _verify(iface, candidate, tentative=False, vtype=None):
    failures = []
    if tentative == False and not iface.providedBy(candidate):
        failures.append(f"Candidate '{candidate.__module__}.{candidate.__name__}' does not claim to implement interface.")

    # Check if all necessary methods are defined
    missing_methods = []
    for method_name in iface.implementedBy():
        if not hasattr(candidate, method_name):
            missing_methods.append(method_name)
    if missing_methods:
        failures.append(f"Missing method(s) in candidate: {', '.join(missing_methods)}")

    # Check if all necessary attributes are defined
    missing_attributes = []
    for attr_name in iface.providedBy():
        if not hasattr(candidate, attr_name):
            missing_attributes.append(attr_name)
    if missing_attributes:
        failures.append(f"Missing attribute(s) in candidate: {', '.join(missing_attributes)}")

    if failures:
        raise Invalid(f"Interface verification failed. Errors:\n{'\n'.join(failures)}")
    return True

