    # Search for an explicit metaclass specified by the user
    elif explicit_mc:
        # Get the metaclass of the user- provided explicit metaclass if available
        explicit_mc = getattr explicit_mc, '__metaclass__', None)

    # Return the determined metaclass or None if neither found
    return explicit_mc or None

