def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    def replace_word(text: str) -> str:
        try:
            return replacer(text.lower())
        except TypeError:
            return text

    tags = set()
    lines = text.split('\n')
    in_code_block = False

    for i, line in enumerate(lines):
        if line.startswith('#') or in_code_block:
            in_code_block = False
            continue

        parts = line.split(' ')
        tag = parts[0]
        if tag.startswith('#'):
            tag = tag[1:]
        if tag not in tags:
            tags.add(tag)

    if replacer is not None:
        lines = [replace_word(line) for line in lines]

    return tags, '\n'.join(lines)

from typing import List, Tuple, Set

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code = False
    start_tag = '#<'
    end_tag = '#>'
    for line in text.split('\n'):
        if not line.strip():
            in_code = False
            continue

        if in_code:
            if line.strip().startswith(start_tag) and line.strip().endswith(end_tag):
                tags.add(line.strip()[len(start_tag):-len(end_tag)])
        else:
            if line.strip().startswith(start_tag):
                in_code = True
                for i in range(len(line) - 1, -1, -1):
                    if line[i] not in '#\t ':
                        break
                tags.add(line[i + 1:-len(end_tag)])
            elif line.strip().startswith(end_tag):
                tags.add(line.strip()[len(end_tag):])

        if replacer:
            for tag in tags.copy():
                text = text.replace(tag, replacer(tag))

    return tags, text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def add_attributes(url, size, context):
        return 'href="{}"'.format(url)

    def process_link(text, size, context):
        scheme, netloc, path, params, query, fragment = urllib.parse.urlparse(text[:size])
        if path:
            link = process_text_link_that_might_be_a_file(path, size)
            return add_attributes(link, size, context)
        return text[:size]

    def process_text_link_that_might_be_a_file(path, size):
        match = PATH_RE.findall(text, size)
        for m in match:
            if any(m.startswith(path) for path inIGNORE_PATHS):
                continue
            return m

    def process_links(match):
        for m in match:
            link = process_text_link(m[:link_size], link_size, context)
            text = text[:link_size] + link + text[link_size:]
            link_size += len(link)
        return text, link_size

    PATH_RE = re.compile(r'\b(http[s]?://[^ ]+)\b', re.IGNORECASE)
    IGNORE_PATHS = ['static', 'css', 'js', 'images', 'assets']
    text, link_size = process_links(match)
    text, link_size = process_text_link_that_might_be_a_file(text, link_size)
    text, link_size = add_attributes(text, link_size, context)

    return text

