import urllib.request

def fetch_content_type(url):
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, path, query, fragment = urllib.parse.urlsplit(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = urllib.request.HeadRequest(url, headers={'Host': netloc})
    try:
        with urllib.request.urlopen(req) as resp:
            if resp.code != 200:
                return None
            return resp.info().get('content-type', None)
    except Exception as e:
        print(f"Error fetching content type: {e}")
        return None

import urllib.request

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    if not url:
        return None

    req = urllib.request.head(url)
    try:
        if hasattr(req, 'code') and req.code not in (200, 301, 302) and isinstance(req, urllib.request.HTTPResponse):
            return None
        return req.info().get('content-type', '')
    finally:
        req.close()

