import yaml

from typing import Optional

def validate_from_content(cls: type, spec_content: Optional[str]) -> dict:
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise ValueError("spec_content argument must be supplied")

    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing YAML content: {e}")

    missing_fields = []
    for key, field in spec.items():
        if not field.required:
            continue
        if key not in spec:
            missing_fields.append(key)

    if missing_fields:
        raise ValueError(f"Mandatory fields missing in the spec: {missing_fields}")

    return spec

def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise ValueError("spec_content argument must be supplied")

    data_spec = yaml.safe_load(spec_content)
    missing_fields = []
    for field in data_spec["required"]:
        if field not in data_spec["data"]:
            missing_fields.append(field)

    if missing_fields:
        raise ValueError(
            "These fields are mandatory in the spec file: {}".format(
                ", ".join(missing_fields))
        )

    return data_spec["data"]

def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """

    if spec_content is None:
        spec_content = cls.load_spec_from_file()

    if not all(field in spec_content for field in cls.required_fields):
        raise IRValidatorException("Mandatory data is missing in spec file")

    return cls.load_data_from_yaml(spec_content)

