    def validate_from_file(cls, yaml_file: Path):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """

        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        default_schema = json.load(open(cls.default_schema_file, 'r'))

        # even though we are using the yaml package to load,
        # it supports JSON and YAML
        try:
            data = yaml.safe_load open(yaml_file, 'r'), Loader=Loader)
        except Exception as e:
            raise IRValidatorException(f"There was a problem parsing the file.\n" + str(e))

        try:
            if 'type' in data:
                custom_schema = cls.load_custom_schema(data['type'])
                jsonschema.validate(data, custom_schema)
            else:
                jsonschema.validate(data, default_schema)

        except ValidationError as ve:
            raise IRValidatorException(f"{ve.message} in {str(ve.instance)}")

        if cls.has_errors(yaml_file):
            raise IRValidatorException("Validation errors found in the file.")

        return data

