    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars is not None:
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[var] = None
    else:
        vars_dict = {}  # return empty dictionary if extra_vars is None

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    if not isinstance(vars_dict, dict):
        raise ValueError("Vars_dict must be of type dictionary")

    if not isinstance(extra_vars, list):
        raise ValueError("Extra_vars must be of type list")

    for extra_var in extra_vars:
        if extra_var not in vars_dict:
            vars_dict[extra_var] = extra_var

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict.copy()

    if isinstance(vars_dict, dict):
        if isinstance(extra_vars, list):
            for ext in extra_vars:
                vars_dict.update(ext)
        else:
            raise ValueError("Invalid input format for extra-vars")

    elif isinstance(vars_dict, list):
        if isinstance(extra_vars, list):
            vars_dict.extend(extra_vars)
        else:
            raise ValueError("Invalid input format for extra-vars")

    return vars_dict.copy()

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not vars_dict:
        return extra_vars

    if not extra_vars:
        return vars_dict

    for extra_var in extra_vars:
        for key, value in extra_var.items():
            if key not in vars_dict:
                vars_dict[key] = value
            elif isinstance(vars_dict[key], list):
                vars_dict[key].append(value)
            else:
                vars_dict[key] = [vars_dict[key], value]

