def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os

    spec = os.path.join(plugin_dir, 'plugin_spec.json')
    with open(spec, 'r') as f:
        plugin_spec = json.load(f)

    flatten_dict = {}
    class_fields = ['version', 'labels', 'properties', 'permissions']
    model_fields = ['model', 'task', 'tasks']

    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            if key in class_fields:
                flatten_dict[key] = [cls_field for cls_field in class_fields if cls_field in value]
            elif key in model_fields:
                flatten_dict[key] = [model_field for model_field in model_fields if model_field in value]
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}__{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value

    return flatten_dict

